import os, glob, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')

    # Parse demo pairs from the log
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    matches = list(re.finditer(pattern, t))

    G = {}  # key: task_id, value: grid
    for match in matches:
        type_str, task_id, h, w = match.groups()
        rows_text = t[match.end():].split('\n')[0:min(h, 20)].strip().split('\n')
        if task_id not in G and all(len(r.split()) == w and all(x.isdigit() for x in r.split()[:min(w,5)]) for r in rows_text):
            try:
                G[task_id] = [[int(cell.split()[0]) for cell in row.split()] for row in rows_text]
                if compute_hash(G[task_id]) is not None:
                    print(f"Loaded {task_id} - {h}x{w}")
                else:
                    G.pop(task_id)
            except:
                pass
    return G, matches

G, matches = load()
print("Demo pairs found:", len([m for m in matches if 'Demo' in m.group(1)]))
print("Test input task:", [m for m in matches if 'Test' in m.group(1)])

def compute_hash(grid):
    if isinstance(grid, list):
        return compute_hash(grid[0]) if grid else None
    return hash(str(grid))

print("\n--- Looking for task-ae4f6ffa ---")
task_id = "task-ae4f6ffa"
if task_id in G:
    print(f"Task {task_id} already loaded!")
    for i, row in enumerate(G[task_id]):
        if i < 3 or i >= G[task_id][0].__len__() - 3:
            print(f"  {row[:10]}...") if i > 0 and len(row) > 10 else print(f"  {row if i != G[task_id][0].__len__() - 1 else '...'}")
else:
    print(f"Task {task_id} not in loaded demos. Need to request demos.")

# Also check env var
print("\nChecking environment...")
print(f"RLM_SESSION_DIR: {os.environ.get('RLM_SESSION_DIR', 'NOT SET')}")

